#include <vector>

class Solution {
public:
    int distinctGatePathsToLCA(int n, std::vector<std::vector<int>>& edges, int gate1, int gate2) {
        std::vector<std::vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        std::vector<int> parent(n, -1), depth(n, 0);
        std::vector<std::pair<int, int>> stack = {{0, -1}};
        while (!stack.empty()) {
            auto [u, p] = stack.back();
            stack.pop_back();
            parent[u] = p;
            for (int v : adj[u]) {
                if (v != p) {
                    depth[v] = depth[u] + 1;
                    stack.push_back({v, u});
                }
            }
        }
        int u = gate1, v = gate2, d1 = 0, d2 = 0;
        while (depth[u] > depth[v]) { u = parent[u]; d1++; }
        while (depth[v] > depth[u]) { v = parent[v]; d2++; }
        while (u != v) {
            u = parent[u];
            v = parent[v];
            d1++;
            d2++;
        }
        return d1 + d2;
    }
};

import java.util.*;

class Solution {
    public int distinctGatePathsToLCA(int n, int[][] edges, int gate1, int gate2) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int[] parent = new int[n];
        int[] depth = new int[n];
        Arrays.fill(parent, -1);
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, -1});
        while (!stack.isEmpty()) {
            int[] top = stack.pop();
            int u = top[0], p = top[1];
            parent[u] = p;
            for (int v : adj.get(u)) {
                if (v != p) {
                    depth[v] = depth[u] + 1;
                    stack.push(new int[]{v, u});
                }
            }
        }
        int u = gate1, v = gate2, d1 = 0, d2 = 0;
        while (depth[u] > depth[v]) { u = parent[u]; d1++; }
        while (depth[v] > depth[u]) { v = parent[v]; d2++; }
        while (u != v) {
            u = parent[u];
            v = parent[v];
            d1++;
            d2++;
        }
        return d1 + d2;
    }
}

